import sys
MOD = 10**9 + 7

def main():
    import sys
    import math
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    a = int(input[2])
    b = int(input[3])

    def count_beautiful_trees(n, m, a, b):
        if abs(a - b) > m:
            return 0
        if abs(a - b) == m:
            return pow(2, n - 2, MOD)
        if m == 1:
            return 0

        def comb(n, k):
            if k > n - k:
                k = n - k
            res = 1
            for i in range(k):
                res = res * (n - i) * pow(i + 1, MOD - 2, MOD) % MOD
            return res

        total_ways = pow(2, n - 2, MOD)
        invalid_ways = 0

        for d in range(abs(a - b) + 1, m + 1):
            invalid_ways += comb(m, d) * pow(2, n - 3, MOD)
            invalid_ways %= MOD

        return (total_ways - invalid_ways + MOD) % MOD

    print(count_beautiful_trees(n, m, a, b))

if __name__ == "__main__":
    main()
